// Which open notes get the "File generated by Focal Registry" pill: the two files the Scan Notes
// sync rewrites, in any folder and with either slash. Every path here is made up and nothing is
// read from disk.
import assert from "node:assert/strict";
import { test } from "node:test";
import { isGeneratedSource } from "../src/shared/generatedSource";

test("Folder-Notes.md and Folder-Report.md are generated in any folder, with either slash", () => {
  const generated = [
    "Q:\\Fake Tree\\Q Drive\\2019\\Fake Shoot\\Folder-Notes.md",
    "Q:\\Fake Tree\\Q Drive\\2019\\Fake Shoot\\Folder-Report.md",
    "Q:/Fake Tree/Q Drive/2019/Fake Shoot/Folder-Notes.md",
    "Q:/Fake Tree/Q Drive/2019/Fake Shoot/Folder-Report.md",
    "Q:\\Fake Tree/mixed\\slashes/Folder-Notes.md",
    "/fake/home/anywhere/Folder-Report.md",
    "Folder-Notes.md",
  ];
  for (const p of generated) assert.equal(isGeneratedSource(p), true, p);
});

test("letter case does not matter, because Windows does not tell the two spellings apart", () => {
  assert.equal(isGeneratedSource("Q:\\Fake Tree\\folder-notes.md"), true);
  assert.equal(isGeneratedSource("Q:/Fake Tree/FOLDER-REPORT.MD"), true);
});

test("an ordinary note is not generated", () => {
  const ordinary = [
    "Q:\\Fake Notes\\Meeting.md",
    "Q:/Fake Notes/README.md",
    "Q:\\Fake Notes\\My Folder-Notes.md", // the whole name has to match, not just its tail
    "Q:\\Fake Notes\\Folder-Notes-2.md",
    "Q:\\Fake Notes\\Folder-Notes.md.txt",
    "Q:\\Fake Notes\\Folder-Notes",
    "Q:\\Fake Notes\\Folder-Notes.md\\Inside.md", // a folder with the name does not mark the files in it
    "Q:/Fake Notes/Folder-Report.md/",
    "Q:\\_FocalRegistry-Reports\\SCAN-Fake-2026-01-02.md", // a scan report is written once, never rewritten
  ];
  for (const p of ordinary) assert.equal(isGeneratedSource(p), false, p);
});

test("a note written in the app has no source file and is not generated", () => {
  assert.equal(isGeneratedSource(null), false);
  assert.equal(isGeneratedSource(undefined), false);
  assert.equal(isGeneratedSource(""), false);
});
